import{_ as a,o as t,c as s,a0 as l}from"./chunks/framework.MyDJm6cd.js";const u=JSON.parse('{"title":"fleetd 席位控制权（seat control）设计","description":"","frontmatter":{},"headers":[],"relativePath":"seat-control.md","filePath":"seat-control.md"}'),o={name:"seat-control.md"};function n(i,e,d,c,r,p){return t(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="fleetd-席位控制权-seat-control-设计" tabindex="-1">fleetd 席位控制权（seat control）设计 <a class="header-anchor" href="#fleetd-席位控制权-seat-control-设计" aria-label="Permalink to &quot;fleetd 席位控制权（seat control）设计&quot;">​</a></h1><p>用户令（2026-11-26 深夜）：claude 席位必须完全受 fleetd 控制，杜绝 「用户说停了席位还在跑/会话被自动重建」这类失控。falcon 事件已定性： 席位会话脱离控制自主 commit+push，停止令没有执行闭环。</p><h2 id="目标-一个控制面-两种权力" tabindex="-1">目标：一个控制面，两种权力 <a class="header-anchor" href="#目标-一个控制面-两种权力" aria-label="Permalink to &quot;目标：一个控制面，两种权力&quot;">​</a></h2><p>fleetd 是<strong>唯一</strong>有资格启动/停止 claude 席位的组件。人对 fleetd 下令， fleetd 对 tmux/claude 执行。其他一切路径（手工 fire_seat、散脚本、 schtasks 残留）全部收编或废除。</p><h3 id="权力-1-绝对停止-stop-三层斩" tabindex="-1">权力 1：绝对停止（stop = 三层斩） <a class="header-anchor" href="#权力-1-绝对停止-stop-三层斩" aria-label="Permalink to &quot;权力 1：绝对停止（stop = 三层斩）&quot;">​</a></h3><p><code>fleetd seat stop &lt;name&gt;</code> 一次执行：</p><ol><li><strong>杀会话</strong>：<code>tmux kill-session -t &lt;name&gt;</code></li><li><strong>杀进程</strong>：<code>pkill -f &quot;workspaces/&lt;name&gt;&quot;</code>（pane 内 claude 及子进程）</li><li><strong>写闸</strong>：台账 seats 表 <code>status=&#39;disabled&#39;</code>——闸门状态的席位， 一切自动启动路径（idle-watch / fire / agent 心跳 / 巡检续作）见到 disabled 必须跳过，这是硬规则不是惯例。</li></ol><p>「退出会话」= stop。没有只杀会话不杀进程、或只杀进程不写闸的中间态。 三层缺一即失控（falcon 复活事故的根因就是只做了第 1 层）。</p><h3 id="权力-2-受控启动-start-唯一入口" tabindex="-1">权力 2：受控启动（start 唯一入口） <a class="header-anchor" href="#权力-2-受控启动-start-唯一入口" aria-label="Permalink to &quot;权力 2：受控启动（start 唯一入口）&quot;">​</a></h3><p><code>fleetd seat start &lt;name&gt; [--task &lt;file&gt;]</code>：</p><ul><li>闸门检查：disabled → 拒绝并提示 <code>seat enable &lt;name&gt;</code> 先解闸。</li><li>建会话、起 claude、登记台账，一切启动动作走这一个函数。</li><li><code>fleetd seat enable &lt;name&gt;</code> 才能把 disabled 翻回 idle——显式、留痕。</li></ul><h3 id="自动化面的收编" tabindex="-1">自动化面的收编 <a class="header-anchor" href="#自动化面的收编" aria-label="Permalink to &quot;自动化面的收编&quot;">​</a></h3><ul><li>idle-watch / 巡检 / 内容巡逻：只<strong>观测</strong>（capture/对账），对 disabled 席位零动作；对 idle 席位的自动点火必须先查闸。</li><li>fleet-arch-diagrams / fleet-i18n-all 这类批处理脚本：从 cron 体系中 移除（无 cron 即无触发）；要跑必须显式经 fleetd job 并逐仓点名。</li><li>schtasks / 计划任务残留（Session1Test、FleetdAhkMcp 等）：tools 面 落地时统一登记，fleetd <code>tools list</code> 可见、<code>tools stop</code> 可停。</li></ul><h3 id="台账字段-seats-表升级" tabindex="-1">台账字段（seats 表升级） <a class="header-anchor" href="#台账字段-seats-表升级" aria-label="Permalink to &quot;台账字段（seats 表升级）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status: idle | running | disabled      ← disabled = 闸门</span></span>
<span class="line"><span>stopped_by TEXT                        ← &#39;user&#39; | &#39;agent&#39; | &#39;crash&#39;</span></span>
<span class="line"><span>stopped_at INTEGER</span></span></code></pre></div><h3 id="命令面-fleetd-seat-子命令" tabindex="-1">命令面（fleetd seat 子命令） <a class="header-anchor" href="#命令面-fleetd-seat-子命令" aria-label="Permalink to &quot;命令面（fleetd seat 子命令）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fleetd seat stop &lt;name&gt;      # 三层斩 + 写闸</span></span>
<span class="line"><span>fleetd seat start &lt;name&gt;     # 检闸 + 建会话 + 登记</span></span>
<span class="line"><span>fleetd seat enable &lt;name&gt;    # 解闸</span></span>
<span class="line"><span>fleetd seat disable &lt;name&gt;   # 只写闸（不杀当前，防复发）</span></span>
<span class="line"><span>fleetd seat list             # 全席位 + 闸门状态</span></span></code></pre></div><h2 id="falcon-事故复盘-作为验收反例" tabindex="-1">falcon 事故复盘（作为验收反例） <a class="header-anchor" href="#falcon-事故复盘-作为验收反例" aria-label="Permalink to &quot;falcon 事故复盘（作为验收反例）&quot;">​</a></h2><ol><li>用户令停 → 只 kill 了 tmux 会话（第 1 层），pane 内 claude 进程没死 → 它继续在后台跑完手头任务并 commit+push。</li><li>会话 22:53 被某个保留名单机制重建 → 没有闸门概念，名单里有就重建。</li><li>巡检对 falcon 的引用散在 4 个脚本 + session-priority.txt 名单， 无统一闸门可查。</li></ol><p>验收：<code>seat stop falcon</code> 后 —— 无 tmux 会话、无进程、台账 disabled、 任何自动路径不点火、<code>seat list</code> 显示 disabled。复测 24h 无复活。</p><h2 id="实现顺序" tabindex="-1">实现顺序 <a class="header-anchor" href="#实现顺序" aria-label="Permalink to &quot;实现顺序&quot;">​</a></h2><ol><li>seats 表迁移 + 三层斩 stop（今日）</li><li>start/enable/disable/list 命令面（今日）</li><li>巡检/idle-watch/名单元数据清理 falcon 引用（今日）</li><li>自动化面统一查闸（跟 agent pull 模式一起）</li></ol>`,22)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
